package com.tnc.tnc.arcana;
import com.tnc.tnc.life.routes.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;

/** Only the explicitly enabled disposable PCL audit invokes these scenes. */
public final class TechnologyNativeScenes {
    public static boolean actualSponsoredRelease;
    private static RouteNodeEntity put(ServerLevel l,BlockPos at,RouteKind kind,ServerPlayer p){l.setBlock(at,RouteContent.NODES.get(kind.id).get().defaultBlockState(),3);var n=(RouteNodeEntity)l.getBlockEntity(at);n.owner=p.getUUID();return n;}
    public static void prepare(ServerPlayer p,int scene,BlockPos base){var l=p.server.overworld();base=base.offset(0,0,100);p.teleportTo(l,base.getX()+.5,base.getY()+3,base.getZ()+7.5,180,20);l.setDayTime(18000);com.tnc.tnc.mana.sight.ManaSightServer.subscribe(p,true);ArcanaPhysiology.data(p).putDouble("vision_sanity",0);ArcanaPhysiology.data(p).putLong("NextSpirit",Long.MAX_VALUE);
        if(scene<=29){for(int x=-6;x<=8;x++)for(int z=-5;z<=8;z++){for(int y=0;y<6;y++)l.setBlock(base.offset(x,y,z),Blocks.AIR.defaultBlockState(),3);l.setBlock(base.offset(x,-1,z),Blocks.DEEPSLATE_TILES.defaultBlockState(),3);}for(int x:new int[]{-4,4})l.setBlock(base.offset(x,-1,2),Blocks.SEA_LANTERN.defaultBlockState(),3);}
        if(scene==27){RouteKind[] all={RouteKind.EXTRACTOR,RouteKind.IGNITER,RouteKind.LEYLINE_COMPASS,RouteKind.RESONANCE,RouteKind.FUMIGATOR,RouteKind.PHASE_SHIFTER};for(int i=0;i<6;i++){var n=put(l,base.offset(-3+(i%3)*3,0,-2+(i/3)*3),all[i],p);n.mana=100;if(all[i]==RouteKind.EXTRACTOR)n.inventory.setItem(0,new ItemStack(ArcanaContent.item("mana_root_core")));if(all[i]==RouteKind.PHASE_SHIFTER)n.inventory.setItem(0,new ItemStack(Items.MAGMA_CREAM));}p.connection.teleport(base.getX()+.5,base.getY()+3.4,base.getZ()+8.5,180,20);}
        if(scene==28){p.connection.teleport(base.getX()+.5,base.getY()+1.5,base.getZ()+3.5,180,20);var n=put(l,base,RouteKind.EXTRACTOR,p);n.mana=150;n.inventory.setItem(0,new ItemStack(ArcanaContent.item("stone_pattern_leaf"),8));for(int i=0;i<3;i++)ArcanaTechnology.tick(l,n);net.minecraftforge.network.NetworkHooks.openScreen(p,n,b->{b.writeBlockPos(n.getBlockPos());b.writeVarInt(n.kind().ordinal());});}
        if(scene==29){var source=put(l,base.offset(-3,0,0),RouteKind.LUNAR,p);source.receive(15000);ArcanaEnergy.credit(source,"lunar",15000);var phase=put(l,base.offset(-1,0,0),RouteKind.PHASE_SHIFTER,p);phase.inventory.setItem(0,new ItemStack(Items.MAGMA_CREAM));var altar=put(l,base.offset(2,0,0),RouteKind.NURTURE,p);altar.inventory.setItem(0,new ItemStack(ArcanaContent.item("fire_wand_3")));for(int x:new int[]{-2,0,1})put(l,base.offset(x,0,0),RouteKind.CRYSTAL_WIRE,p);p.connection.teleport(base.getX()+.5,base.getY()+2.1,base.getZ()+5.5,180,13);}
        if(scene==32){var tower=put(l,base.offset(2,0,0),RouteKind.ABYSS_TOWER,p);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<3;y++)if(x!=0||z!=0)l.setBlock(tower.getBlockPos().offset(x,y,z),ArcanaContent.TOWER_BRICK.defaultBlockState(),3);tower.receive(100000);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(ArcanaContent.item("fire_wand_3")));var magic=com.tnc.tnc.magic.MagicStone.getOrNull(p);var entry=com.tnc.tnc.magic.SpellCatalog.all().stream().filter(e->e.element()==com.tnc.tnc.magic.Element.FIRE&&e.tier()==3&&e.chain()==com.tnc.tnc.magic.SpellCatalog.Chain.BALL).findFirst().orElseThrow();magic.learn(entry.id());magic.setMana(magic.getMaxMana());ArcanaPhysiology.data(p).remove("MealSunUntil");com.tnc.tnc.magic.compat.SpellEngineBridge.ensureWand(p,magic.getLearned());int before=magic.getMana(),stored=tower.mana;long releases=ArcanaBeacon.committed,shots=ArcanaBeacon.snapshots;var result=com.tnc.tnc.magic.compat.SpellEngineCaster.cast(p,entry.id());int cost=com.tnc.tnc.equipment.MageGear.spellCost(p,entry.manaCostFor(magic.getMaxMana()));actualSponsoredRelease=result.error()==null&&ArcanaBeacon.committed==releases+1&&ArcanaBeacon.snapshots>shots&&tower.mana==stored-cost&&magic.getMana()==before&&ArcanaBeacon.scale(p)==1&&ArcanaBeacon.reserved(tower)==0;}
        if(scene==30||scene==31){var nether=p.server.getLevel(Level.NETHER);if(nether==null)throw new IllegalStateException("Missing actual Nether");var at=new BlockPos(base.getX(),160,base.getZ()+100);nether.getChunkAt(at);if(nether.getBlockEntity(at) instanceof RouteNodeEntity old)RouteMirrorLinks.unlink(nether,old);
            for(int x=-8;x<=8;x++)for(int z=-8;z<=26;z++){for(int y=0;y<=10;y++)nether.setBlock(at.offset(x,y,z),Blocks.AIR.defaultBlockState(),3);nether.setBlock(at.offset(x,-1,z),x%5==0&&z%5==0?Blocks.SHROOMLIGHT.defaultBlockState():Blocks.POLISHED_BLACKSTONE_BRICKS.defaultBlockState(),3);}
            // Respect the pack gate: this disposable audit account has completed its existing unlock.
            try{((net.minecraft.nbt.CompoundTag)p.getClass().getMethod("kjs$getPersistentData").invoke(p)).putBoolean("the_nether",true);}catch(ReflectiveOperationException error){throw new IllegalStateException("Audit requires the installed KubeJS player data API",error);}var dest=put(nether,at,RouteKind.DIMENSION_PRISM,p);p.teleportTo(nether,at.getX()+.5,at.getY()+3,at.getZ()+18.5,180,-12);if(p.serverLevel()!=nether)throw new IllegalStateException("Pack blocked Nether travel");
            if(scene==31){var tower=put(l,base.offset(20,0,0),RouteKind.ABYSS_TOWER,p);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<3;y++)if(x!=0||z!=0)l.setBlock(tower.getBlockPos().offset(x,y,z),ArcanaContent.TOWER_BRICK.defaultBlockState(),3);tower.receive(500000);var origin=put(l,tower.getBlockPos().offset(2,0,0),RouteKind.DIMENSION_PRISM,p);String error=ArcanaRealms.link(p,GlobalPos.of(l.dimension(),origin.getBlockPos()),GlobalPos.of(nether.dimension(),at));if(!error.isEmpty())throw new IllegalStateException(error);ArcanaRealms.pump(p.server);}
        }
    }
    private TechnologyNativeScenes(){}
}
